using UnityEngine;using System.Reflection;using System.Linq;using System.IO;
string dir=__RUN_DIR__;const BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
Type TypeOf(string name)=>AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType(name)).First(t=>t!=null);
object Read(object target,string name)=>target.GetType().GetProperty(name,flags)?.GetValue(target)??target.GetType().GetField(name,flags)?.GetValue(target);
void Write(object target,string name,object value){var p=target.GetType().GetProperty(name,flags);if(p!=null)p.SetValue(target,value);else target.GetType().GetField(name,flags).SetValue(target,value);}
object Call(object target,string name,params object[] args)=>target.GetType().GetMethod(name,flags).Invoke(target,args);
var game=TypeOf("GameManager");var manager=Object.FindObjectsByType(game).Cast<Component>().First();var roster=game.GetProperty("Players").GetValue(manager);var player=(Component)roster.GetType().GetProperty("LocalPlayer").GetValue(roster);var motor=player.GetComponent(TypeOf("PlayerMotor"));var controller=player.GetComponent(TypeOf("PlayerController"));var body=player.GetComponent<Rigidbody>();body.useGravity=false;body.position=new Vector3(-40,20,-43);player.transform.position=body.position;
await Task.Delay(1500);
var input=Activator.CreateInstance(TypeOf("AnalogInputState"));Call(controller,"InitializeInput",input);Write(input,"Movement",Vector2.right);var start=body.position;await Task.Delay(600);Write(input,"Movement",Vector2.zero);await Task.Delay(100);float moved=Vector3.Distance(start,body.position);if(moved<1.2f||moved>1.9f)throw new Exception("Native local movement failed: "+moved);
