var rootBefore=enemy.transform.position;var hoverBefore=motion.transform.position;await Task.Delay(250);
float hoverDelta=Vector3.Distance(hoverBefore,motion.transform.position);float rootDelta=Vector3.Distance(rootBefore,enemy.transform.position);
if(hoverDelta<.0001f||rootDelta>.01f)throw new Exception("Native levitation missing or moving the navigation root");
var head=enemy.GetComponentsInChildren<Collider>().Single(c=>c.CompareTag("EnemyHead"));
var headOrigin=head.bounds.center+Vector3.up*.3f+Vector3.back*.6f;var headDirection=(head.bounds.center-headOrigin).normalized;
var shootProbe=player.GetComponent(TypeOf("PlayerShoot"));var hitMask=(LayerMask)Read(shootProbe,"_mask");
if(!Physics.Raycast(headOrigin,headDirection,out RaycastHit headHit,2f,hitMask,QueryTriggerInteraction.Ignore)||headHit.collider!=head)throw new Exception("Native bobbing head cannot be targeted independently");
if(!(bool)Call(enemy.GetComponent(TypeOf("EnemyFeedback")),"IsValidImpact",enemy.transform.InverseTransformPoint(headHit.point),enemy.transform.InverseTransformDirection(headHit.normal)))throw new Exception("Bobbing head impact rejected");
var target=enemy.GetComponentsInChildren<Collider>().First(c=>c.CompareTag("EnemyBody"));
var equipment=player.GetComponent(TypeOf("PlayerEquipment"));if(!(bool)Call(equipment,"TryCollectWeapon",1))throw new Exception("Rifle pickup failed");await Task.Delay(100);var weapon=Call(equipment,"getActiveWeapon");Write(weapon,"Mode",Enum.Parse(TypeOf("Weapon+FireMode"),"single"));var camera=(Camera)Read(player.GetComponent(TypeOf("PlayerSetup")),"ActionCamera");camera.transform.position=target.bounds.center+Vector3.back*2;Call(motor,"Rotate",Vector3.up*Mathf.DeltaAngle((float)Read(motor,"ViewYaw"),0));Call(motor,"RotateCamera",(float)Read(motor,"currentCameraRotationX"));Call(motor,"ApplyView");int ammo=(int)Read(weapon,"CurrentMagAmmo");var shoot=player.GetComponent(TypeOf("PlayerShoot"));Call(shoot,"PerformWeaponFire",1f);await Task.Delay(400);int spent=ammo-(int)Read(weapon,"CurrentMagAmmo");float hitHealth=(float)Read(enemy,"_currentHealth");if(spent!=1||Mathf.Abs(hitHealth-(120f-(int)Read(weapon,"Damage")*2f))>.001f)throw new Exception("Native ray/Command failed: "+spent+"/"+hitHealth);
File.WriteAllText(Path.Combine(dir,"shot-ready"),"ready");bool dissolved=false;float maxDissolve=0f;float deadline=Time.realtimeSinceStartup+8;
while(enemy!=null&&Time.realtimeSinceStartup<deadline){var dissolve=enemy.GetComponentInChildren(TypeOf("DissolveEnemyBody"));if(dissolve!=null){maxDissolve=Mathf.Max(maxDissolve,(float)Read(dissolve,"DissolveAmount"));dissolved|=maxDissolve>=1;}await Task.Delay(10);}if(enemy!=null||!dissolved)throw new Exception("Network death/dissolve/despawn failed: exists="+(enemy!=null)+", maxDissolve="+maxDissolve+(File.Exists(Path.Combine(dir,"host-error.txt"))?File.ReadAllText(Path.Combine(dir,"host-error.txt")):""));await Task.Delay(200);
float hp=(float)Read(player,"_currentHealth");var overlay=Object.FindObjectsByType(TypeOf("PlayerDamageOverlay")).Cast<Component>().Single();float opacity=overlay.GetComponent<CanvasRenderer>().GetAlpha();if(hp!=20||Mathf.Abs(opacity-.09f)>.005f)throw new Exception("Replicated low-health feedback failed: "+hp+"/"+opacity);
var cellPosition=JsonUtility.FromJson<Vector3>(File.ReadAllText(Path.Combine(dir,"cell-position.json")));body.isKinematic=true;body.position=cellPosition+Vector3.up;player.transform.position=body.position;await Task.Delay(800);var placement=player.GetComponent(TypeOf("PlacementController"));var counts=(int[])Read(placement,"placeableCount");counts[0]=1;var requests=player.GetComponent(TypeOf("MirrorPlacement"));string cellId=File.ReadAllText(Path.Combine(dir,"cell.txt"));Call(requests,"Place",cellPosition,Quaternion.identity,cellId,0);await Wait.Until(()=>counts[0]==0,5000);File.WriteAllText(Path.Combine(dir,"placed-ready"),"ready");return new{passed=true,moved,spent,hitHealth,hp,opacity,dissolved,placement=true,hoverDelta,rootDelta,headTargetable=true};
